def list_items(category, page, page_size):
    rows = [row for row in ROWS if category == "" or row["category"] == category]
    start = (page - 1) * page_size
    return {"items": rows[start:start + page_size], "total": len(rows), "page": page}

def __init__(self, api, category="books", page=1):
    self.api = api
    self.category = category
    self.page = page

def select_category(self, category):
    self.category = category
    return self.api.get_items(self.category, self.page)

def test_reset_with_recorded_api_call(self):
    class RecordingAPI(CatalogAPI):
        def get_items(self, category, page, page_size=2):
            self.request = (category, page, page_size)
            return super().get_items(category, page, page_size)

    api = RecordingAPI()
    view = CatalogView(api, category='books', page=3)
    view.select_category('tools')
    self.assertEqual(api.request, ('tools', 1, 2))

def __init__(self):
    self.cache = {}

def get_items(self, category, page, page_size=2):
    key = (page, page_size)
    if key not in self.cache:
        self.cache[key] = list_items(category, page, page_size)
    return self.cache[key]

